export const ELEMENTS = RAW.map(([symbol, name, radius, mass, color], i) => ({ z: i + 1, symbol, name, radius, mass, color }));
export const BY_SYMBOL = Object.fromEntries(ELEMENTS.map((e) => [e.symbol, e]));

const UNKNOWN = { z: 0, symbol: 'X', name: 'Unknown', radius: 1.5, mass: 1, color: '#b3b3b3' };

export function element(symbol) {
    return BY_SYMBOL[normalizeSymbol(symbol)] || UNKNOWN;
}

// Accepts labels such as "Fe", "FE", "Fe2+", "O1" or "Si_a" and returns a symbol.
export function normalizeSymbol(raw) {
    if (!raw) return 'X';
    const m = String(raw).trim().match(/^([A-Za-z])([A-Za-z]?)/);
    if (!m) return 'X';
    const two = m[1].toUpperCase() + (m[2] || '').toLowerCase();
    if (BY_SYMBOL[two]) return two;
    const one = m[1].toUpperCase();
    return BY_SYMBOL[one] ? one : two;
}
